entries[288503] = { ["name"] = "Umbrabrauner Nachtsäbler", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren umbrabraunen Nachtsäbler oder gibt ihn wieder frei.\n\"Nachtsäbler sind ein wesentlicher Bestandteil der Armee der Kaldorei und dienen gleichermaßen als Reittiere und Angriffswaffen.\"\nBeute von:\nMoxo der Köpfer\nZone:\nDunkelküste\n\nBeute von:\nAthil Tauglanz\nZone:\nDunkelküste" }
