entries[288505] = { ["name"] = "Nachtsäbler der Kaldorei", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren Nachtsäbler der Kaldorei oder gibt ihn wieder frei.\n\"Die Verbindung zwischen Nachtsäbler und seinem Jäger oder seiner Jägerin ist kaum zu brechen.\"\nBeute von:\nCroz Blutzorn\nZone:\nDunkelküste\n\nBeute von:\nSchattenklaue\nZone:\nDunkelküste" }
entries[288506] = { ["name"] = "Goldbrauner Nachtsäbler", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren goldbrauner Nachtsäbler oder gibt ihn wieder frei.\n\"Nachtsäbler dieser Farbe sind sehr selten und kaum zu finden. Bei Jägerinnen erfreuen sie sich großer Beliebtheit.\"\nVerkäufer:\nVersorgerin Starkschmied\nZone:\nTiragardesund\nKosten:\n350\n\nVerkäufer:\nVersorgerin Mukra\nZone:\nZuldazar\nKosten:\n350" }
