entries[288711] = { ["name"] = "Salzwasserseepferdchen", ["text"] = "Wirken in 1.5 sek.\nBeschwört ein reitbares Salzwasserseepferdchen oder gibt es wieder frei. Dieses Reittier ist ein geschickter Schwimmer.\n\nAufgrund seiner kapriziösen Natur kann seine Schwimmgeschwindigkeit durch Effekte, die die Reitgeschwindigkeit erhöhen oder verringern, nicht beeinflusst werden.\n\"Diese riesigen Seepferde sind von Natur aus neugierig und durchsuchen oft versunkene Schiffswracks nach Glitzerkram.\"\nVerkäufer:\nKapitänin Klarisa\nZone:\nTiragardesund\nKosten:\n500\n\nVerkäufer:\nKapitänin Zen'taga\nZone:\nZuldazar\nKosten:\n500" }
entries[288712] = { ["name"] = "Steinhauturhorn", ["text"] = "Wirken in 1.5 sek.\nBeschwört Euer Steinhauturhorn oder gibt es wieder frei.\n\"Die Steinhauturhörner sind eine von wenigen Elcharten, die das Inselklima vertragen, da ihr Fell dünner ausfällt als bei den meisten Urhörnern.\"\nBeute von:\nInselexpeditionen" }
