entries[288719] = { ["name"] = "Blitzeis", ["text"] = "300 Meter Reichweite\nWirken in 5 sek.\nJaina beginnt, alles einzufrieren, und belegt alle Spielercharaktere alle 6 Sek. mit einem Stapel von ' Eiskalte Berührung ', während ein Kältebereich sich langsam von ihrer Position ausbreitet. Spielercharaktere, die diesen Bereich berühren, werden sofort eingefroren.\n\nNach Ende der Kanalisierung zertrümmert Jaina alle Spielercharaktere und tötet sie sofort." }
entries[288720] = { ["name"] = "Blutgesättigter Jäger", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Wenn er nicht so voll wäre, hättet Ihr ihn nicht erwischt.\"\nBeute von:\nInselexpeditionen" }
